import { useState } from 'react';
import {
  Pressable,
  SafeAreaView,
  Platform,
  ScrollView,
  StatusBar,
  StyleSheet,
  Text,
  useColorScheme,
  View,
} from 'react-native';
// @generated by scripts/gen-registry.mjs (region: screen-imports) - do not edit; run bun run regen
import ButtonScreen from './ButtonScreen';
import DatePickerScreen from './DatePickerScreen';
import PickerScreen from './PickerScreen';
import ProgressScreen from './ProgressScreen';
import SegmentedControlScreen from './SegmentedControlScreen';
import SliderScreen from './SliderScreen';
import SwitchScreen from './SwitchScreen';
import MenuScreen from './MenuScreen';
import DialogScreen from './DialogScreen';
import BottomSheetScreen from './BottomSheetScreen';
import TextFieldScreen from './TextFieldScreen';
import ChipScreen from './ChipScreen';
import CheckboxScreen from './CheckboxScreen';
import ContextMenuScreen from './ContextMenuScreen';
import SearchFieldScreen from './SearchFieldScreen';
import TooltipScreen from './TooltipScreen';
// @end-generated
// `Host` has no manifest (it is a container, not a control), so its screen is the
// one import the registry does not write.
import HostScreen from './HostScreen';
// `Form` is the S6/S6b spike prototype: no manifest, so the registry writes neither its
// tab nor its screen. It is here because `real-input` can only prove what the app
// renders, and the iOS taps S6 could not take need a Form on screen.
import FormScreen from './FormScreen';

type Screen =
  // @generated by scripts/gen-registry.mjs (region: screens) - do not edit; run bun run regen
  | 'switch'
  | 'slider'
  | 'button'
  | 'progress'
  | 'segmented'
  | 'datepicker'
  | 'picker'
  | 'menu'
  | 'dialog'
  | 'sheet'
  | 'textfield'
  | 'chip'
  | 'checkbox'
  | 'contextmenu'
  | 'searchfield'
  | 'tooltip'
  // @end-generated
  // Neither of these is a control with a manifest, so the generator writes neither line: `host`
  // is the shared-composition screen, and `form` is the S6/S6b spike prototype whose
  // screen `real-input` needs in order to tap a reparented row.
  | 'host'
  | 'form';

/**
 * Which screen a cold launch shows.
 *
 * A constant rather than a build-time variable: Metro only inlines `NODE_ENV`
 * here, so an `process.env`-based switch would need a Metro config for one
 * developer convenience. Task screenshots are taken with this flipped (see the
 * task report), which needs no Metro change and no rebuild of anything else.
 *
 * Keep the committed value a screen the window can go idle on, and land it back
 * here after a screenshot session. The Progress screen draws two indeterminate
 * indicators and starts its 60 Hz writer on mount, so on Android that window
 * never idles: `uiautomator dump` answers "could not get idle state", and
 * `bun run test:real-input:android` - which reads the screen that way - then
 * never sees the tab bar and times out (A2 measured it: the same timeout on
 * `main` and on this branch, and a dump that succeeds one tab over).
 */
const DEFAULT_SCREEN: Screen = 'switch';

/**
 * The tab bar's top padding.
 *
 * RN's `SafeAreaView` is iOS-only, and Android lays apps out edge to edge, so on
 * Android the tabs drew under the clock - the round-1 review's screenshots.
 * `StatusBar.currentHeight` is core's answer for that inset on Android and `null`
 * on iOS, where `SafeAreaView` is already doing the work, so this covers both
 * without taking `react-native-safe-area-context` into the example for one tab
 * bar. A display cutout taller than the status bar would still overlap; the
 * example is not where to solve that.
 */
const topInset =
  Platform.select({ android: StatusBar.currentHeight, default: 0 }) ?? 0;

/**
 * The smallest a tab may be, both ways: Android's 48 dp and Apple's 44 pt touch
 * target. `scripts/real-input/tab-targets.mjs` (`TAB_TARGET_MIN`) holds both suites
 * to the same two numbers, measured on the device.
 */
const TAB_MIN = Platform.select({ android: 48, default: 44 });

const TABS: { id: Screen; label: string }[] = [
  // @generated by scripts/gen-registry.mjs (region: tabs) - do not edit; run bun run regen
  { id: 'switch', label: 'Switch' },
  { id: 'slider', label: 'Slider' },
  { id: 'button', label: 'Button' },
  { id: 'progress', label: 'Progress' },
  { id: 'segmented', label: 'Segments' },
  { id: 'datepicker', label: 'Dates' },
  { id: 'picker', label: 'Picker' },
  { id: 'menu', label: 'Menu' },
  { id: 'dialog', label: 'Dialogs' },
  { id: 'sheet', label: 'Sheet' },
  { id: 'textfield', label: 'Text' },
  { id: 'chip', label: 'Chip' },
  { id: 'checkbox', label: 'Checkbox' },
  { id: 'contextmenu', label: 'Context' },
  { id: 'searchfield', label: 'Search' },
  { id: 'tooltip', label: 'Tooltip' },
  // @end-generated
  // The shared-`<Host>` screen: real-input taps it (iOS included, where `Host` is the
  // passthrough) and `Host.harness.tsx` measures it. `Host` composes on Android only.
  { id: 'host', label: 'Host' },
  { id: 'form', label: 'Form' },
];

/**
 * Playground for the library. T10 put the Switch tracer bullet here; G1 added
 * the Slider, G2 the Button and G3 the Progress; every task adds a screen.
 *
 * The tabs are the only navigation: the harness renders its own UI, and a
 * screenshot of the example app is a screenshot of whichever screen is showing.
 */
export default function App() {
  const [screen, setScreen] = useState<Screen>(DEFAULT_SCREEN);
  const dark = useColorScheme() === 'dark';

  return (
    <View style={[styles.root, dark ? null : styles.rootLight]}>
      <SafeAreaView style={[styles.tabs, dark ? null : styles.tabsLight]}>
        {/* Scrolls sideways rather than sharing one row: a row split 15 ways gave
            each tab about 23 x 28 dp on Android (X19). `handled` lets a tab take the
            tap while a text field's keyboard is up, as the plain row did. */}
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          keyboardShouldPersistTaps="handled"
          contentContainerStyle={styles.tabRow}
        >
          {TABS.map((tab) => (
            <Pressable
              key={tab.id}
              onPress={() => setScreen(tab.id)}
              testID={`tab-${tab.id}`}
              style={[
                styles.tab,
                screen === tab.id &&
                  (dark ? styles.tabActive : styles.tabActiveLight),
              ]}
            >
              <Text
                numberOfLines={1}
                style={[
                  styles.tabLabel,
                  screen === tab.id && (dark ? styles.ink : styles.inkLight),
                ]}
              >
                {tab.label}
              </Text>
            </Pressable>
          ))}
        </ScrollView>
      </SafeAreaView>
      <View style={styles.body}>
        {/* @generated by scripts/gen-registry.mjs (region: screens-body) - do not edit; run bun run regen */}
        {screen === 'switch' ? <SwitchScreen /> : null}
        {screen === 'slider' ? <SliderScreen /> : null}
        {screen === 'button' ? <ButtonScreen /> : null}
        {screen === 'progress' ? <ProgressScreen /> : null}
        {screen === 'segmented' ? <SegmentedControlScreen /> : null}
        {screen === 'datepicker' ? <DatePickerScreen /> : null}
        {screen === 'picker' ? <PickerScreen /> : null}
        {screen === 'menu' ? <MenuScreen /> : null}
        {screen === 'dialog' ? <DialogScreen /> : null}
        {screen === 'sheet' ? <BottomSheetScreen /> : null}
        {screen === 'textfield' ? <TextFieldScreen /> : null}
        {screen === 'chip' ? <ChipScreen /> : null}
        {screen === 'checkbox' ? <CheckboxScreen /> : null}
        {screen === 'contextmenu' ? <ContextMenuScreen /> : null}
        {screen === 'searchfield' ? <SearchFieldScreen /> : null}
        {screen === 'tooltip' ? <TooltipScreen /> : null}
        {/* @end-generated */}
        {screen === 'host' ? <HostScreen /> : null}
        {screen === 'form' ? <FormScreen /> : null}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  root: {
    flex: 1,
    backgroundColor: '#000',
  },
  rootLight: {
    backgroundColor: '#fff',
  },
  tabs: {
    paddingTop: topInset,
    backgroundColor: '#111',
  },
  tabsLight: {
    backgroundColor: '#ececec',
  },
  tabRow: {
    gap: 4,
    paddingHorizontal: 4,
  },
  /**
   * Each tab keeps its natural width and is never smaller than a touch target.
   *
   * The row used to share the window equally (`flex: 1`) so that every tab stayed on
   * screen - a tab drawn past the window's edge could not take a real tap (G5's Picker
   * tab, at x 434 of a 420 pt window). Fifteen tabs later that made every tab too small
   * to tap reliably, so the bar scrolls instead, and the navigators scroll a tab into
   * view before they tap it (`goToTab` in `RealInputTests.swift`, `revealTab` in
   * `scripts/real-input/android.mjs`).
   *
   * The bar is exactly one tab tall: a taller bar costs the body height, and a body
   * 32 pt shorter flipped where UIKit anchors a `DatePicker` popover (G5's anchoring
   * check). The label is centred inside the 44 / 48 target rather than padded around.
   */
  tab: {
    minWidth: TAB_MIN,
    minHeight: TAB_MIN,
    paddingHorizontal: 12,
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: 8,
  },
  tabActive: {
    backgroundColor: '#333',
  },
  tabActiveLight: {
    backgroundColor: '#d5d5d8',
  },
  tabLabel: {
    color: '#9d9da2',
    fontSize: 14,
  },
  ink: {
    color: '#fff',
  },
  inkLight: {
    color: '#000',
  },
  body: {
    flex: 1,
  },
});
